<?php $me=(int)(user()['id']??0); ?>
<main class="main"><div class="main__inner"><div class="module-page">
<header class="module-page__header"><div><nav class="breadcrumb" aria-label="Breadcrumb"><span>Portal</span><i data-lucide="chevron-right"></i><span>Messages</span></nav><h1>Messages</h1><p>Your conversations with the institute.</p></div></header>
<section class="module-card"><div class="module-card__body"><details class="messaging-compose"<?=!$conversations?' open':''?>><summary><i data-lucide="square-pen"></i>Start a new conversation</summary><form method="post" action="<?=e(url('/portal/messages'))?>" class="module-form"><?=csrf_field()?><div class="module-form-grid"><div class="module-field"><label for="recipient_id">Recipient</label><select class="module-input" id="recipient_id" name="recipient_id" required><option value="">Select a recipient</option><?php foreach($recipients as$r):?><option value="<?=(int)$r['id']?>"><?=e($r['name'])?></option><?php endforeach?></select></div><div class="module-field"><label for="subject">Subject <span class="optional-label">Optional</span></label><input class="module-input" id="subject" name="subject" type="text" maxlength="150"></div><div class="module-field field--wide"><label for="body">Message</label><textarea class="module-textarea" id="body" name="body" rows="3" required></textarea></div></div><div class="filter-actions"><button class="btn btn--primary" type="submit"><i data-lucide="send"></i>Send message</button></div></form></details></div></section>
<section class="module-card portal-inbox-layout" aria-label="Your conversations"><aside class="portal-thread-list"><header class="portal-thread-list__header"><h2>Inbox</h2><p class="record-count"><?=count($conversations)?> conversations</p></header><?php foreach($conversations as$c):$name=$c['participant_name']?:$c['subject']?:'Conversation';?><a class="portal-thread-item conversation-item<?=$thread&&(int)$thread['id']===(int)$c['id']?' is-active':''?>" href="<?=e(url('/portal/messages/'.(int)$c['id']))?>"<?=$thread&&(int)$thread['id']===(int)$c['id']?' aria-current="page"':''?>><span class="conversation-avatar" aria-hidden="true"><?=e(strtoupper(substr((string)$name,0,1)))?></span><span class="conversation-copy"><strong><?=e($name)?></strong><small><?=e($c['updated_at'])?></small></span><?php if((int)$c['unread_count']):?><span class="status-badge"><?=(int)$c['unread_count']?> new</span><?php endif?></a><?php endforeach?><?php if(!$conversations):?><div class="compact-empty"><div><span class="compact-empty__icon"><i data-lucide="inbox"></i></span><h3>No conversations</h3><p>Messages you send or receive will appear here.</p></div></div><?php endif?></aside>
<div class="portal-conversation chat-pane"><?php if($thread):?><header class="chat-pane__header"><h2><?=e($thread['subject']?:'Conversation')?></h2><p><?=count($thread['messages'])?> messages</p></header><div class="chat-history"><?php foreach($thread['messages']as$m):?><article class="portal-message<?=((int)$m['sender_id']===$me)?' is-mine':''?>"><strong><?=e($m['sender_name'])?></strong><p><?=nl2br(e($m['body']))?></p><small><?=e($m['created_at'])?></small></article><?php endforeach?></div><form class="chat-reply" method="post" action="<?=e(url('/portal/messages/'.(int)$thread['id']))?>"><?=csrf_field()?><div class="module-field"><label class="sr-only" for="reply">Reply</label><textarea class="module-textarea" id="reply" name="body" rows="2" placeholder="Write a reply…" required></textarea></div><button class="btn btn--primary" type="submit"><i data-lucide="send"></i>Send</button></form><?php else:?><div class="compact-empty"><div><span class="compact-empty__icon"><i data-lucide="message-circle"></i></span><h3>Select a conversation</h3><p>Choose a conversation to read and reply.</p></div></div><?php endif?></div></section>
</div></div></main>
